import { test, expect, type Page } from '@playwright/test'

/**
 * 真实后端 E2E（dev：flood 9610 / auth 9211，经 nginx 8095 同源反代 /api-flood、/api-auth）
 *
 * 登录策略：优先直接调 /api-auth 登录接口拿 token 注入 localStorage(flood-token-v1)，
 *          再打开站点，使其在 remote 模式下带上 Authorization。UI 自动登录（App.vue）作为兜底。
 *
 * 说明：本套用例面向「模板驱动的 remote 页面」（fe-pages 改造后的最终形态）。
 * 若页面未改造 / dist 为旧 demo 构建，用例会如实失败（等待页面/构建），不会伪造通过。
 */

const PROJECT_ID = 'suzhufang'
// 已知明文密码 Zs@2026Aa! 的 AES-256(base64) 密文，避免在测试里实现 AES
const ENCRYPTED_PWD = 'H03W0LoMA6EFQZIW46BnNA=='
const LOGIN_USER = 'zsbase'
const TOKEN_KEY = 'flood-token-v1'

/** 调登录接口拿 accessToken；失败返回 null（交由 UI 自动登录兜底） */
async function fetchToken(page: Page): Promise<string | null> {
  try {
    const res = await page.request.post('/api-auth/v2.0/security/auth/login', {
      headers: { 'Content-Type': 'application/json', 'zhi-project-id': PROJECT_ID },
      data: { username: LOGIN_USER, password: ENCRYPTED_PWD },
    })
    if (!res.ok()) return null
    const body = await res.json().catch(() => null) as { code?: number; data?: { accessToken?: string; token?: string } } | null
    return body?.data?.accessToken ?? body?.data?.token ?? null
  } catch {
    return null
  }
}

/** 注入 token 到 localStorage 后再访问站点，确保首屏请求即带 Authorization */
async function openSite(page: Page, hash = '/') {
  const token = await fetchToken(page)
  if (token) {
    await page.addInitScript(([k, v]) => {
      try { window.localStorage.setItem(k as string, v as string) } catch { /* ignore */ }
    }, [TOKEN_KEY, token] as const)
  }
  await page.goto(hash, { waitUntil: 'networkidle' }).catch(() => page.goto(hash))
  // 若未注入成功，App.vue 自动登录会拿 token；给一点时间让首屏数据请求完成
  await page.waitForTimeout(1000)
}

/** 在检查页为数值项填写数值（优先原生输入，否则点"增加"按钮累计到目标值） */
async function fillNumber(page: Page, target: number) {
  // 1) 原生数字输入框直接填
  const numericInputs = page.locator('input[type="number"], input[inputmode="numeric"], input[inputmode="decimal"]')
  if (await numericInputs.count()) {
    const first = numericInputs.first()
    await first.fill(String(target))
    return
  }
  // 2) stepper：点"增加"直到达到 target（读取 .stepper-value）
  const inc = page.getByRole('button', { name: /增加|\+$/ }).first()
  if (await inc.count()) {
    const valueEl = page.locator('.stepper-value').first()
    const start = Number((await valueEl.innerText().catch(() => '0')).trim() || '0')
    for (let i = start; i < target; i++) await inc.click()
    return
  }
  // 3) 兜底：任意文本框填数值
  const anyInput = page.locator('input').first()
  await anyInput.fill(String(target))
}

/** 选择物业管理区域：输入关键字 -> 点第一个出现的小区选项 */
async function pickComplex(page: Page, keyword = '小'): Promise<string | null> {
  const searchInput = page
    .locator('input')
    .filter({ hasNot: page.locator('[type="number"]') })
    .or(page.getByPlaceholder(/小区|物业|区域|搜索|请输入/))
    .first()
  await expect(searchInput).toBeVisible({ timeout: 20_000 })
  await searchInput.click()
  await searchInput.fill(keyword)
  // 触发搜索（部分实现需 blur / 回车）
  await searchInput.press('Enter').catch(() => {})
  // 等待下拉选项：以小区名关键字或通用选项容器为准
  const option = page
    .getByRole('option')
    .or(page.locator('[class*="option"], [class*="dropdown"] li, [class*="suggest"] [role="button"]'))
    .filter({ hasText: /小区|花园|新村|苑|家园|华城/ })
    .first()
  await expect(option).toBeVisible({ timeout: 20_000 })
  const name = (await option.innerText()).trim()
  await option.click()
  return name
}

test.describe('真实后端 E2E：登录 → 填报 → 提交 → 历史 → 详情', () => {
  test.beforeEach(async ({ page }) => {
    // 每个用例独立 context：清空 localStorage，重新注入 token
    await page.context().clearCookies()
  })

  test('场景1+2：进入汛中巡检，模板检查项渲染，选择物业管理区域', async ({ page }) => {
    await openSite(page, '/')
    // 工作台可见
    await expect(page.getByText('工作台').first()).toBeVisible({ timeout: 20_000 })
    // 进入汛中巡检
    await page.getByRole('button', { name: /汛中巡检/ }).click()
    // 模板检查项渲染：至少一个检查项字段可见（label 文本）
    await expect(page.locator('.sec-item-label, .field-label, [class*="item-label"]').first()).toBeVisible({ timeout: 20_000 })
    // 选择物业管理区域（关键字"小"）
    const name = await pickComplex(page, '小')
    expect(name).toBeTruthy()
  })

  test('场景3：填数值 8 并提交，出现提交成功/工单编号', async ({ page }) => {
    await openSite(page, '/#/pages/inspection/index?kind=mid')
    // 等待模板项就绪
    await expect(page.locator('.sec-item-label, .field-label').first()).toBeVisible({ timeout: 20_000 })
    // 选物业区域（提交前必填）
    await pickComplex(page, '小')
    // 填数值 8
    await fillNumber(page, 8)
    // 提交
    await page.getByRole('button', { name: /提\s*交/ }).first().click()
    // 成功提示或工单编号
    await expect(page.getByText(/提交成功|工单编号|XZXJ/i).first()).toBeVisible({ timeout: 30_000 })
  })

  test('场景4+5：提交后进入历史可见记录，点开详情展示检查项与小区名', async ({ page }) => {
    // 先提交一条（汛中）
    await openSite(page, '/#/pages/inspection/index?kind=mid')
    await expect(page.locator('.sec-item-label, .field-label').first()).toBeVisible({ timeout: 20_000 })
    const complexName = await pickComplex(page, '小')
    await fillNumber(page, 8)
    await page.getByRole('button', { name: /提\s*交/ }).first().click()
    const success = page.getByText(/提交成功|工单编号|XZXJ/i).first()
    await expect(success).toBeVisible({ timeout: 30_000 })
    const successText = await success.innerText().catch(() => '')

    // 进入历史记录
    await page.goto('/#/pages/history/index', { waitUntil: 'networkidle' }).catch(() => {})
    await page.waitForTimeout(1500)
    // 回到「汛中巡检」页签（历史页有 tab）
    const midTab = page.getByRole('button', { name: /汛中巡检/ }).first()
    if (await midTab.count()) await midTab.click().catch(() => {})

    // 能看到记录：至少一条 ticket，含工单编号或小区名
    const ticket = page.locator('.ticket, [class*="ticket"]').first()
    await expect(ticket).toBeVisible({ timeout: 20_000 })
    const ticketText = await ticket.innerText()
    // 断言：工单编号可见 或 小区名可见（二者其一）
    const noMatch = /工单编号[：:]\s*\S+/.test(ticketText) || /XZXJ/i.test(ticketText)
    const nameMatch = complexName ? ticketText.includes(complexName) : false
    expect(noMatch || nameMatch).toBeTruthy()

    // 点开详情
    const detailBtn = page.getByRole('button', { name: /查看详情/ }).first()
    if (await detailBtn.count()) await detailBtn.click()
    else await ticket.click()

    // 详情页：展示检查项与小区名
    await expect(page.locator('.detail-hero, [class*="detail"]').first()).toBeVisible({ timeout: 20_000 })
    if (complexName) {
      // 小区名应在详情页出现（表头或明细）
      await expect(page.getByText(complexName, { exact: false }).first()).toBeVisible({ timeout: 20_000 })
    }
    // 至少一个检查项 label 可见
    await expect(page.locator('.detail-row-label, [class*="row-label"]').first()).toBeVisible({ timeout: 20_000 })
  })
})

