import { test } from '@playwright/test'

test('probe inspection DOM', async ({ page, request }) => {
  const login = await request.post('/api-auth/v2.0/security/auth/login', {
    headers: { 'Content-Type': 'application/json', 'zhi-project-id': 'suzhufang' },
    data: { username: 'zsbase', password: 'H03W0LoMA6EFQZIW46BnNA==' },
  })
  const token = (await login.json()).data.accessToken
  const logs: string[] = []
  page.on('console', m => logs.push(`[${m.type()}] ${m.text()}`))
  page.on('pageerror', e => logs.push(`[pageerror] ${e.message}`))
  page.on('response', r => { const u = r.url(); if (u.includes('/api-')) logs.push(`[${r.status()}] ${r.request().method()} ${u}`) })
  await page.addInitScript(([k, v]) => { try { localStorage.setItem(k as string, v as string) } catch {} }, ['flood-token-v1', token] as const)
  await page.goto('/#/pages/inspection/index?kind=mid', { waitUntil: 'networkidle' }).catch(() => {})
  await page.waitForTimeout(3000)
  const body = await page.locator('body').innerText().catch(() => '')
  console.log('=== BODY (first 2000) ===\n' + body.slice(0, 2000))
  const inputs = await page.locator('input').evaluateAll(els => els.map(e => ({ ph: e.getAttribute('placeholder'), aria: e.getAttribute('aria-label'), type: e.getAttribute('type'), cls: e.className })))
  console.log('=== INPUTS ===', JSON.stringify(inputs, null, 1))
  console.log('=== LOGS ===\n' + logs.join('\n'))
})

