/** 选择物业管理区域：uni-app 的 input placeholder 不在 <input> 属性上，用页面上唯一的文本 input */
async function pickComplex(page: Page, keyword = '小'): Promise<string> {
  // 断言占位文案可见（模板驱动页物业区域必填）
  await expect(page.getByText('输入关键词搜索物业管理区域').first()).toBeVisible({ timeout: 20_000 })
  const searchInput = page.locator('input[type="text"], input:not([type])').first()
  await expect(searchInput).toBeVisible({ timeout: 20_000 })
  await searchInput.click()
  await searchInput.fill(keyword)
  // 防抖 250ms 后出下拉选项：role=button，文本=小区名
  const option = page
    .getByRole('button')
    .filter({ hasText: /小区|花园|新村|苑|家园|华城/ })
    .first()
  await expect(option).toBeVisible({ timeout: 20_000 })
  const name = (await option.innerText()).trim().split('\n')[0].trim()
  await option.click()
  // 选中回显校验（页面显示「已选：<小区名>」）
  await expect(page.getByText(name, { exact: false }).first()).toBeVisible({ timeout: 10_000 })
  return name
}

