import { test } from '@playwright/test'

test('probe submit payload', async ({ page, request }) => {
  const login = await request.post('/api-auth/v2.0/security/auth/login', { headers: { 'Content-Type': 'application/json', 'zhi-project-id': 'suzhufang' }, data: { username: 'zsbase', password: 'H03W0LoMA6EFQZIW46BnNA==' } })
  const token = (await login.json()).data.accessToken
  page.on('request', r => { if (r.url().includes('/api-flood/') && (r.method() === 'POST')) console.log('[REQ POST]', r.url(), '\n  BODY:', r.postData()) })
  page.on('response', async r => { if (r.url().includes('/api-flood/') && r.request().method() === 'POST') { const t = await r.text().catch(() => ''); console.log('[RESP]', r.status(), r.url(), '\n  DATA:', t.slice(0, 400)) } })
  await page.addInitScript(([k, v]) => { try { localStorage.setItem(k as string, v as string) } catch {} }, ['flood-token-v1', token] as const)
  await page.goto('/#/pages/inspection/index?kind=mid', { waitUntil: 'networkidle' }).catch(() => {})
  await page.waitForTimeout(2500)
  const si = page.locator('input[type="text"], input:not([type])').first()
  await si.click(); await si.fill('小')
  const opt = page.locator('.complex-option:not(.muted)').first()
  await opt.waitFor({ timeout: 15000 }); await opt.click()
  const inc = page.getByRole('button', { name: '增加' }).first()
  for (let i = 0; i < 8; i++) await inc.click()
  page.on('console', m => console.log('[console]', m.text()))
  await page.getByRole('button', { name: /提\s*交/ }).first().click()
  await page.waitForTimeout(4000)
  const alert = await page.locator('[role="alert"]').innerText().catch(() => '(none)')
  console.log('=== ALERT AFTER SUBMIT ===', alert)
})

import { test } from '@playwright/test'

test('probe full chain with string ids', async ({ request }) => {
  const H = { 'Content-Type': 'application/json', 'zhi-project-id': 'suzhufang' }
  const login = await request.post('/api-auth/v2.0/security/auth/login', { headers: H, data: { username: 'zsbase', password: 'H03W0LoMA6EFQZIW46BnNA==' } })
  const token = (await login.json()).data.accessToken
  const A = { ...H, Authorization: `Bearer ${token}` }
  const ev = await request.get('/api-flood/v2.0/safety/flood/event/page?pageNum=1&pageSize=50', { headers: A })
  const rows = (await ev.json()).rows
  const e3 = rows.find((r: any) => String(r.stage) === '3' && String(r.bizState) === '2')
  console.log('eventId(string) =', e3.eventId)
  const tpl = await request.get(`/api-flood/v2.0/safety/flood/inspection/template?eventId=${e3.eventId}&inspectionStage=3`, { headers: A })
  const items = await tpl.json()
  const itemArr = Array.isArray(items) ? items : items.data
  console.log('template item count =', itemArr.length, 'first templateItemId =', itemArr[0].templateItemId)
  // save with STRING ids (as fix would send)
  const payload = { inspectionStage: '3', subject: 'property', eventId: e3.eventId, complexId: '667577485357516', haveDanger: '0', items: itemArr.map((it: any) => ({ templateItemId: it.templateItemId, fillType: it.fillType, fillValue: '8' })) }
  console.log('SAVE payload =', JSON.stringify(payload))
  const save = await request.post('/api-flood/v2.0/safety/flood/inspection/save', { headers: A, data: payload })
  const saveBody = await save.json().catch(() => ({ raw: save.status() }))
  console.log('SAVE resp =', save.status(), JSON.stringify(saveBody).slice(0, 300))
  const id = saveBody?.data
  if (id != null) {
    const sub = await request.post('/api-flood/v2.0/safety/flood/inspection/submit', { headers: A, data: { id: String(id) } })
    console.log('SUBMIT resp =', sub.status(), (await sub.text()).slice(0, 200))
    const det = await request.get(`/api-flood/v2.0/safety/flood/inspection/${id}`, { headers: A })
    const detBody = await det.json().catch(() => ({}))
    console.log('DETAIL inspectionNo =', detBody?.data?.inspectionNo, 'complexName =', detBody?.data?.complexName, 'items =', (detBody?.data?.items || []).map((x: any) => `${x.checkContent}=${x.fillValue}`))
  }
})

